import React, { useState } from 'react';
import { MapPin, ChevronRight, ChevronLeft, Search, Box, Circle, Triangle, Hexagon } from 'lucide-react';

const AreasZonesTab = () => {
  const [viewLevel, setViewLevel] = useState('ZONES'); 
  const [selectedZone, setSelectedZone] = useState(null);
  const [selectedArea, setSelectedArea] = useState(null);
  const [searchQuery, setSearchQuery] = useState('');

  // --- ENHANCED DATA WITH COLORS ---
  const zoneData = [
    {
      id: 'Z-1', name: 'NORTH_SECTOR', code: 'NS-ALPHA', accent: '#FF5B03', // Sungold
      areas: [
        { id: 'A-1', name: 'Hillside Drive', location: 'North Ridge', code: 'HSD-44', bins: ['BN-401', 'BN-405', 'BN-409'] },
        { id: 'A-2', name: 'University Road', location: 'East Campus', code: 'URD-12', bins: ['BN-502', 'BN-503'] }
      ]
    },
    {
      id: 'Z-2', name: 'CENTRAL_HUB', code: 'CH-BRAVO', accent: '#CAD23C', // Seed Green
      areas: [
        { id: 'A-3', name: 'Main Square', location: 'Downtown', code: 'MSQ-01', bins: ['BN-101', 'BN-102'] }
      ]
    }
  ];

  const displayData = viewLevel === 'ZONES' 
    ? zoneData.filter(z => z.name.includes(searchQuery.toUpperCase()))
    : selectedZone?.areas.filter(a => a.name.toLowerCase().includes(searchQuery.toLowerCase()));

  return (
    <div className="w-full animate-slot flex flex-col gap-12 p-4 min-h-screen">

      {/* 1. UNCONVENTIONAL HEADER: FLOATING NAV */}
      <div className="flex flex-col gap-4 border-l-8 border-[#FF5B03] pl-6 py-2">
        <div className="flex items-center gap-4">
          {viewLevel !== 'ZONES' && (
            <button 
              onClick={() => setViewLevel(viewLevel === 'BINS' ? 'AREAS' : 'ZONES')} 
              className="hover:scale-125 transition-transform text-[#AB1717]"
            >
              <ChevronLeft size={32} strokeWidth={3} />
            </button>
          )}
          <h2 className="text-5xl font-[1000] tracking-tighter text-[#47510B] uppercase italic leading-none">
            {viewLevel === 'ZONES' ? 'Atlas' : viewLevel === 'AREAS' ? selectedZone.name : selectedArea.name}
          </h2>
        </div>

        <div className="flex items-center gap-4">
          <div className="relative flex-grow max-w-md">
            <input 
              type="text" placeholder="FILTER_MATRIX..." 
              className="w-full bg-[#FDFAD8] border-b-4 border-[#A1AED1] p-3 pl-10 text-xs font-black uppercase outline-none focus:border-[#FF5B03] transition-all"
              onChange={(e) => setSearchQuery(e.target.value)}
            />
            <Search className="absolute left-2 top-3 text-[#AB1717]" size={18} />
          </div>
          <div className="hidden md:flex gap-2 text-[10px] font-black text-[#A1AED1]">
            <span className={viewLevel === 'ZONES' ? 'text-[#FF5B03]' : ''}>01_ZONES</span>
            <span>/</span>
            <span className={viewLevel === 'AREAS' ? 'text-[#FF5B03]' : ''}>02_AREAS</span>
            <span>/</span>
            <span className={viewLevel === 'BINS' ? 'text-[#FF5B03]' : ''}>03_NODES</span>
          </div>
        </div>
      </div>

      {/* 2. LEVEL 1: ZONES (STAGGERED TYPOGRAPHY STYLE) */}
      {viewLevel === 'ZONES' && (
        <div className="flex flex-col gap-16 mt-10">
          {displayData.map((zone, i) => (
            <div 
              key={zone.id} 
              onClick={() => {setSelectedZone(zone); setViewLevel('AREAS');}}
              className="group cursor-pointer flex items-center gap-8 relative"
            >
              <span className="text-7xl font-black text-[#A1AED1]/20 italic group-hover:text-[#FFB6A9]/40 transition-colors">0{i+1}</span>
              <div className="flex flex-col">
                <div className="flex items-center gap-3">
                  <div className="h-[2px] w-12 bg-[#FF5B03] group-hover:w-24 transition-all" />
                  <span className="text-xs font-black text-[#AB1717] tracking-[0.4em]">{zone.code}</span>
                </div>
                <h3 className="text-6xl font-[1000] text-[#47510B] group-hover:text-[#FF5B03] group-hover:italic transition-all duration-300">
                  {zone.name}
                </h3>
              </div>
              <div className="ml-auto opacity-0 group-hover:opacity-100 transition-opacity flex flex-col items-end">
                 <span className="text-[10px] font-black text-[#47510B]">EXPLORE_SECTOR</span>
                 <ChevronRight size={48} strokeWidth={1} className="text-[#FF5B03]" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 3. LEVEL 2: AREAS (DOT-MATRIX PATH STYLE) */}
      {viewLevel === 'AREAS' && (
        <div className="flex flex-col gap-2 border-l-2 border-dashed border-[#A1AED1] ml-6">
          {displayData.map((area) => (
            <div 
              key={area.id} 
              onClick={() => {setSelectedArea(area); setViewLevel('BINS');}}
              className="group flex items-center p-8 -ml-[13px] hover:bg-[#FFF24D] transition-all relative cursor-crosshair"
            >
              <div className="w-6 h-6 rounded-full bg-white border-4 border-[#AB1717] group-hover:scale-150 transition-transform" />
              <div className="ml-10">
                <h4 className="text-3xl font-black text-[#47510B] uppercase">{area.name}</h4>
                <div className="flex gap-4 mt-1">
                  <span className="bg-[#FFB6A9] text-[#AB1717] text-[10px] px-2 font-black uppercase">{area.code}</span>
                  <span className="text-[#A1AED1] text-[10px] font-black uppercase tracking-widest">{area.location}</span>
                </div>
              </div>
              <div className="ml-auto border-2 border-[#47510B] px-6 py-2 group-hover:bg-[#47510B] group-hover:text-white transition-all">
                <span className="text-sm font-black italic">{area.bins.length} UNITS</span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 4. LEVEL 3: BINS (THE HEX-GRID) */}
      {viewLevel === 'BINS' && (
        <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-10">
          {selectedArea.bins.map((binId) => (
            <div key={binId} className="relative group cursor-pointer">
              {/* Decorative Background Shape */}
              <div className="absolute inset-0 bg-[#CAD23C] translate-x-3 translate-y-3 group-hover:translate-x-0 group-hover:translate-y-0 transition-transform" />
              <div className="relative bg-[#47510B] p-8 flex flex-col items-center justify-center border-2 border-[#47510B]">
                <Box className="text-[#FF5B03] mb-4 group-hover:rotate-12 transition-transform" size={32} />
                <span className="text-[#FDFAD8] font-mono font-black text-lg tracking-tighter">{binId}</span>
                <div className="absolute top-2 right-2 w-2 h-2 bg-[#FFF24D] rounded-full animate-pulse" />
              </div>
            </div>
          ))}
        </div>
      )}

      {/* BOTTOM DECORATION */}
      <div className="mt-auto pt-20 flex justify-between items-center opacity-30">
        <div className="h-[1px] flex-grow bg-[#A1AED1]" />
        <div className="px-4 text-[8px] font-black tracking-[1em] text-[#47510B]">TRASH2TRACK_CORE_v2.0</div>
        <div className="h-[1px] flex-grow bg-[#A1AED1]" />
      </div>

    </div>
  );
};

export default AreasZonesTab;
